import { createPublicClient, http } from 'viem';
import { base } from 'viem/chains';

const API = 'https://api.gentechlabs.net';
const WALLET = '0x...'; // your wallet

// 1. Call a paid endpoint → get 402 + payment challenge
const res = await fetch(`${API}/v1/security/score/0x8e53ad52980478794bb5b459b7cbdd836975e4cb`, {
  headers: { Accept: 'application/json' }
});

if (res.status === 402) {
  const payment = await res.json(); // { scheme, network, amount, asset, payTo }

  // 2. Sign the payment request with your wallet
  const signature = await signPayment(payment, WALLET);

  // 3. Retry with the proof
  const data = await fetch(`${API}/v1/security/score/0x8e53ad52980478794bb5b459b7cbdd836975e4cb`, {
    headers: {
      'Payment-Signature': signature,
      'Payment-Response': 'base64-encoded-response'
    }
  }).then(r => r.json());

  console.log(data);
}
